const rawInput = $input.first()?.json || {};
const body = rawInput.body && typeof rawInput.body === 'object' ? rawInput.body : rawInput;

const isWebhook = Boolean(rawInput.headers || rawInput.webhookUrl || body.action);
let action = (body.action || (isWebhook ? 'replay' : 'live')).toString().trim().toLowerCase();

if (!['live', 'replay', 'backfill_embeddings'].includes(action)) {
  action = 'replay';
}

return [
  {
    json: {
      action,
      act_number: body.act_number ? String(body.act_number).trim() : null,
      ordinance_id: body.ordinance_id ? String(body.ordinance_id).trim() : null,
      force_redeliver: body.force_redeliver !== undefined ? Boolean(body.force_redeliver) : true,
      rss_url: body.rss_url || $env.RFB_RSS_URL || 'http://normas.receita.fazenda.gov.br/sijut2consulta/rss.action',
      custom_ordinance: body.custom_ordinance || null,
      triggered_at: new Date().toISOString()
    }
  }
];

const crypto = require('crypto');
const items = $input.all();
const triggerMeta = $('Normalizar Entrada e Modo').first()?.json || {};

const TAX_REFORM_REGEX = /\b(IBS|CBS|Imposto\s+Seletivo|LC\s*214|EC\s*132|Split\s+Payment|IVA|PIS|COFINS|ICMS|ISS|NFS-?e|Redutor|Cesta\s+B[aá]sica|Regime\s+Espec[ií]fico)\b/i;

function stripHtml(html) {
  return String(html || '')
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/gi, '$1')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

const candidates = [];

if (triggerMeta.custom_ordinance && typeof triggerMeta.custom_ordinance === 'object') {
  const custom = triggerMeta.custom_ordinance;
  const rawText = stripHtml(`${custom.act_number || ''} ${custom.title || ''} ${custom.raw_excerpt || ''}`);
  const hash = crypto.createHash('sha256').update(custom.official_url || rawText).digest('hex');
  candidates.push({
    external_hash: hash,
    act_number: custom.act_number || 'ATO NORMATIVO RFB/DOU',
    title: custom.title || 'Ato Normativo da Reforma Tributária',
    official_url: custom.official_url || 'http://normas.receita.fazenda.gov.br/',
    published_at: custom.published_at || new Date().toISOString().slice(0, 10),
    raw_excerpt: rawText.slice(0, 6000)
  });
} else {
  const rawPayload = items[0]?.json?.data || items[0]?.json?.body || '';
  const itemRegex = /<item[^>]*>([\s\S]*?)<\/item>/gi;
  let match;
  while ((match = itemRegex.exec(rawPayload)) !== null) {
    const block = match[1];
    const titleMatch = block.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
    const linkMatch = block.match(/<link[^>]*>([\s\S]*?)<\/link>/i);
    const descMatch = block.match(/<description[^>]*>([\s\S]*?)<\/description>/i);
    const pubDateMatch = block.match(/<pubDate[^>]*>([\s\S]*?)<\/pubDate>/i);

    const title = stripHtml(titleMatch ? titleMatch[1] : '');
    const officialUrl = stripHtml(linkMatch ? linkMatch[1] : '');
    const description = stripHtml(descMatch ? descMatch[1] : '');
    const fullText = `${title}\n\n${description}`.trim();

    if (!fullText || !TAX_REFORM_REGEX.test(fullText)) {
      continue;
    }

    const actNumberMatch = title.match(/^((?:Instru[cç][aã]o\s+Normativa|Portaria|Ato\s+Declarat[oó]rio|Resolu[cç][aã]o|Lei\s+Complementar|Soluc[aã]o\s+de\s+Consulta)[^-–:]*)/i);
    const actNumber = actNumberMatch ? actNumberMatch[1].trim() : title.slice(0, 80);

    let publishedAt = new Date().toISOString().slice(0, 10);
    if (pubDateMatch) {
      const parsedDate = new Date(stripHtml(pubDateMatch[1]));
      if (!isNaN(parsedDate.getTime())) {
        publishedAt = parsedDate.toISOString().slice(0, 10);
      }
    }

    const externalHash = crypto
      .createHash('sha256')
      .update(`${officialUrl}|${actNumber}|${title}`)
      .digest('hex');

    candidates.push({
      external_hash: externalHash,
      act_number: actNumber,
      title,
      official_url: officialUrl || 'http://normas.receita.fazenda.gov.br/',
      published_at: publishedAt,
      raw_excerpt: fullText.slice(0, 6000)
    });
  }
}

return candidates.slice(0, 10).map((c) => ({ json: c }));

