const VALID_SLUGS = new Set([
  'tecnologia_saas',
  'saude_servicos_medicos',
  'educacao',
  'agronegocio',
  'varejo_comercio',
  'industria_manufatura',
  'construcao_imobiliario',
  'transporte_logistica',
  'servicos_financeiros',
  'alimentacao_hotelaria',
  'profissoes_regulamentadas',
  'energia_combustiveis_telecom'
]);

const sourceItem = $('IF - Ato Inédito?').item.json;
const geminiResp = $input.item.json;
const rawText =
  geminiResp?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';

let parsed;
try {
  parsed = typeof rawText === 'object' ? rawText : JSON.parse(rawText);
} catch (err) {
  const cleaned = String(rawText).replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
  parsed = JSON.parse(cleaned);
}

const escopo = parsed.escopo === 'GERAL' ? 'GERAL' : 'ESPECIFICO_SETORIAL';
const grauUrgencia = ['ALTA', 'MEDIA', 'BAIXA'].includes(parsed.grau_urgencia)
  ? parsed.grau_urgencia
  : 'MEDIA';

const validSlugs = Array.isArray(parsed.affected_sector_slugs)
  ? parsed.affected_sector_slugs.filter((s) => VALID_SLUGS.has(s))
  : [];

const setoresAfetados = Array.isArray(parsed.setores_afetados)
  ? parsed.setores_afetados
      .filter((item) => item && VALID_SLUGS.has(item.setor_slug))
      .map((item) => ({
        setor_slug: item.setor_slug,
        setor_nome: item.setor_nome || item.setor_slug,
        resumo_impacto_setor: item.resumo_impacto_setor || parsed.resumo_geral || '',
        acao_recomendada: item.acao_recomendada || 'Avaliar impactos junto à contabilidade.'
      }))
  : [];

const tributos = Array.isArray(parsed.tributos) && parsed.tributos.length > 0
  ? parsed.tributos.map((t) => String(t).trim())
  : ['IBS', 'CBS'];

const embeddingInputText = [
  sourceItem.act_number,
  parsed.titulo_curto || sourceItem.title,
  parsed.resumo_geral || '',
  setoresAfetados.map((s) => `${s.setor_nome}: ${s.resumo_impacto_setor}`).join(' | '),
  sourceItem.raw_excerpt
].join('\n').slice(0, 7500);

return {
  json: {
    external_hash: sourceItem.external_hash,
    act_number: sourceItem.act_number,
    title: parsed.titulo_curto || sourceItem.title,
    official_url: sourceItem.official_url,
    published_at: sourceItem.published_at,
    raw_excerpt: sourceItem.raw_excerpt,
    relevante_tributario: Boolean(parsed.relevante_tributario ?? true),
    escopo,
    grau_urgencia: grauUrgencia,
    tributos,
    affected_sector_slugs: validSlugs,
    setores_afetados_detalhe: setoresAfetados,
    resumo_geral: parsed.resumo_geral || sourceItem.title,
    previsao_vigencia: parsed.previsao_mudanca_vigencia || 'Conforme cronograma LC 214/2025',
    embedding_input_text: embeddingInputText
  }
};

const meta = $('IF - Relevante Tributário?').item.json;
const embValues = $input.item.json?.embedding?.values || [];
const vectorLiteral = Array.isArray(embValues) && embValues.length === 768
  ? `[${embValues.join(',')}]`
  : null;

const toPgTextArray = (arr) => {
  if (!Array.isArray(arr) || arr.length === 0) return '{}';
  return '{' + arr.map((v) => '"' + String(v).replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"').join(',') + '}';
};

return {
  json: {
    ...meta,
    tributos_pg: toPgTextArray(meta.tributos),
    affected_sector_slugs_pg: toPgTextArray(meta.affected_sector_slugs),
    setores_afetados_json: JSON.stringify(meta.setores_afetados_detalhe || []),
    vector_literal: vectorLiteral
  }
};

const rows = $input.all();
const DISCLAIMER = '⚠️ Aviso Legal: Este alerta é gerado de forma automatizada pelo assistente Fiscália em caráter meramente informativo e educacional, não substituindo consultoria jurídica ou contábil formal.';

const urgencyBadge = {
  ALTA: '🔴 URGÊNCIA ALTA',
  MEDIA: '🟡 URGÊNCIA MÉDIA',
  BAIXA: '🟢 URGÊNCIA BAIXA'
};

return rows.map((item) => {
  const row = item.json;
  const badge = urgencyBadge[row.grau_urgencia] || '🟡 ALERTA TRIBUTÁRIO';
  const tributosStr = Array.isArray(row.tributos) && row.tributos.length > 0
    ? row.tributos.join(', ')
    : 'IBS / CBS';
  const sectorNamesStr = Array.isArray(row.matched_sector_names) && row.matched_sector_names.length > 0
    ? row.matched_sector_names.join(', ')
    : 'Setores Monitorados';

  let impacts = [];
  if (Array.isArray(row.matched_impacts)) {
    impacts = row.matched_impacts;
  } else if (typeof row.matched_impacts === 'string') {
    try {
      impacts = JSON.parse(row.matched_impacts);
    } catch (e) {
      impacts = [];
    }
  }

  const impactsTelegramLines = impacts.length > 0
    ? impacts.map((imp) => {
        const nome = imp.setor_nome || imp.setor_slug || 'Setor Impactado';
        const resumo = imp.resumo_impacto_setor || row.resumo_geral;
        const acao = imp.acao_recomendada || 'Revisar procedimentos fiscais com sua contabilidade.';
        return `📌 *${nome}*\n• *Impacto:* ${resumo}\n• *Ação Recomendada:* ${acao}`;
      }).join('\n\n')
    : `📌 *${sectorNamesStr}*\n• *Impacto:* ${row.resumo_geral}\n• *Ação Recomendada:* Avaliar adequação aos novos leiautes e regras da LC 214/2025.`;

  const telegramText = [
    `🏛️ *FISCÁLIA — ALERTA DA REFORMA TRIBUTÁRIA*`,
    `${badge} | Escopo: *${row.escopo}*`,
    ``,
    `📄 *${row.act_number}*`,
    `_${row.title}_`,
    ``,
    `👤 *Assinante:* ${row.display_name || 'Contribuinte'}`,
    `🎯 *Seus Setores Impactados:* ${sectorNamesStr}`,
    `💰 *Tributos:* ${tributosStr}`,
    `📅 *Vigência / Prazo:* ${row.previsao_vigencia || 'Conforme LC 214/2025'}`,
    ``,
    `📋 *Resumo Executivo:*`,
    `${row.resumo_geral}`,
    ``,
    `🔍 *Impacto Consolidado nos Seus Setores:*`,
    impactsTelegramLines,
    ``,
    `🔗 *Texto Oficial (DOU/RFB):* ${row.official_url}`,
    ``,
    `_${DISCLAIMER}_`
  ].join('\n');

  const slackBlocks = [
    {
      type: 'header',
      text: {
        type: 'plain_text',
        text: `🏛️ Fiscália | ${badge}: ${row.act_number}`.slice(0, 150),
        emoji: true
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*${row.title}*\n${row.resumo_geral}`
      }
    },
    {
      type: 'section',
      fields: [
        {
          type: 'mrkdwn',
          text: `*Setores Impactados:*\n${sectorNamesStr}`
        },
        {
          type: 'mrkdwn',
          text: `*Tributos / Escopo:*\n${tributosStr} (${row.escopo})`
        },
        {
          type: 'mrkdwn',
          text: `*Previsão de Vigência:*\n${row.previsao_vigencia || 'Imediata / LC 214'}`
        },
        {
          type: 'mrkdwn',
          text: `*Fonte Oficial:*\n<${row.official_url}|Abrir Ato no DOU / RFB>`
        }
      ]
    },
    {
      type: 'divider'
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `* Detalhamento Consolidado para seus Setores:*\n\n${impactsTelegramLines}`
      }
    },
    {
      type: 'context',
      elements: [
        {
          type: 'mrkdwn',
          text: DISCLAIMER
        }
      ]
    }
  ];

  const hasTelegramToken = Boolean($env.TELEGRAM_BOT_TOKEN && !String($env.TELEGRAM_BOT_TOKEN).includes('your_'));
  const hasSlackToken = Boolean($env.SLACK_BOT_TOKEN && !String($env.SLACK_BOT_TOKEN).includes('your_'));

  return {
    json: {
      ...row,
      telegram_text: telegramText,
      slack_blocks: slackBlocks,
      slack_fallback_text: `[Fiscália] ${badge} - ${row.act_number}: ${row.title}`,
      can_send_telegram: row.channel_type === 'telegram' && hasTelegramToken,
      can_send_slack: row.channel_type === 'slack' && hasSlackToken
    }
  };
});

const sourceAlert = $('Switch - Canal de Notificação').item.json;
const apiResult = $input.item.json;

return {
  json: {
    ordinance_id: sourceAlert.ordinance_id,
    act_number: sourceAlert.act_number,
    user_id: sourceAlert.user_id,
    channel_type: sourceAlert.channel_type,
    chat_id: sourceAlert.chat_id,
    matched_sector_slugs: sourceAlert.matched_sector_slugs,
    delivery_api_response: apiResult
  }
};

const items = $input.all();
const mode = $('Normalizar Entrada e Modo').first()?.json?.action || 'replay';

return [
  {
    json: {
      status: 'ok',
      mode,
      dispatched_alerts_count: items.filter((i) => i.json && (i.json.id || i.json.user_id)).length,
      completed_at: new Date().toISOString(),
      details: items.map((i) => i.json)
    }
  }
];

const ord = $('IF - Existem Atos Sem Embedding?').item.json;
const values = $input.item.json?.embedding?.values || [];

if (!Array.isArray(values) || values.length !== 768) {
  throw new Error(`Embedding inválido retornado para ordinance ${ord.id}: esperado 768 dimensões, recebido ${values.length}`);
}

return {
  json: {
    id: ord.id,
    act_number: ord.act_number,
    vector_literal: `[${values.join(',')}]`
  }
};

const updated = $input.all().filter((i) => i.json && i.json.id);
return [
  {
    json: {
      status: 'ok',
      mode: 'backfill_embeddings',
      updated_count: updated.length,
      updated_ordinances: updated.map((i) => ({
        id: i.json.id,
        act_number: i.json.act_number,
        title: i.json.title
      })),
      completed_at: new Date().toISOString()
    }
  }
];
